/**
 * Edge cases of the {@code agg:} extension aggregates driven at the collector level (one method per case of the GH-6193
 * edge-case plan). Cases that need query context (GROUP BY, HAVING, DISTINCT equality of SPARQL terms, window
 * functions, sub-select ordering) live in the MemoryStore SPARQL tests.
 */
class ExtensionAggregatesEdgeCaseTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static final Literal EMPTY_JSON_ARRAY = VF.createLiteral("[]", CoreDatatype.RDF.JSON);

	private static final List<AbstractUnaryAggregateFactory> UNARY = List.of(new MedianAggregateFactory(),
			new ModeAggregateFactory(), new CountIfAggregateFactory(), new BoolAndAggregateFactory(),
			new BoolOrAggregateFactory(), new FirstAggregateFactory(), new LastAggregateFactory(),
			new ApproxCountDistinctAggregateFactory(), new HistogramAggregateFactory(),
			new ArrayAggAggregateFactory());

	private static final List<AbstractNAryAggregateFactory> NARY = List.of(new PercentileContAggregateFactory(),
			new PercentileDiscAggregateFactory(), new ApproxQuantileAggregateFactory(), new CorrAggregateFactory(),
			new CovarPopAggregateFactory(), new CovarSampAggregateFactory(), new ArgMinAggregateFactory(),
			new ArgMaxAggregateFactory());

	private static Literal integer(long v) {
		return VF.createLiteral(BigInteger.valueOf(v));
	}

	private static Literal decimal(String v) {
		return VF.createLiteral(new BigDecimal(v));
	}

	private static Literal dbl(double v) {
		return VF.createLiteral(v);
	}

	private static Literal str(String v) {
		return VF.createLiteral(v);
	}

	private static BindingSet row(Value x) {
		QueryBindingSet bs = new QueryBindingSet(2);
		if (x != null) {
			bs.addBinding("x", x);
		}
		return bs;
	}

	private static BindingSet row(Value x, Value y) {
		QueryBindingSet bs = new QueryBindingSet(2);
		if (x != null) {
			bs.addBinding("x", x);
		}
		if (y != null) {
			bs.addBinding("y", y);
		}
		return bs;
	}

	/** Runs a unary aggregate over the given values; {@code null} stands for an unbound value. */
	@SuppressWarnings("unchecked")
	private static Value unary(AbstractUnaryAggregateFactory factory, boolean distinct, Value... values) {
		return unaryWith(factory, distinct, bs -> bs.getValue("x"), values);
	}

	@SuppressWarnings("unchecked")
	private static Value unaryWith(AbstractUnaryAggregateFactory factory, boolean distinct,
			Function<BindingSet, Value> step, Value... values) {
		ExtensionCollector collector = factory.getCollector();
		AggregateFunction<ExtensionCollector, Value> function = factory.buildFunction(step);
		Set<Value> seen = new HashSet<>();
		for (Value value : values) {
			function.processAggregate(row(value), distinct ? seen::add : v -> true, collector);
		}
		return collector.getFinalValue();
	}

	/** Runs a two-argument aggregate over {@code (x, y)} rows; {@code null} stands for an unbound value. */
	@SuppressWarnings("unchecked")
	private static Value nary(AbstractNAryAggregateFactory factory, boolean distinct, Value[]... rows) {
		ExtensionCollector collector = factory.getCollector();
		AggregateNAryFunction<ExtensionCollector, Value> function = factory
				.buildFunction((i, bs) -> bs.getValue(i == 0 ? "x" : "y"));
		Set<List<Value>> seen = new HashSet<>();
		for (Value[] r : rows) {
			function.processAggregate(row(r[0], r[1]), distinct ? seen::add : v -> true, collector);
		}
		return collector.getFinalValue();
	}

	private static Value[] pair(Value x, Value y) {
		return new Value[] { x, y };
	}

	private static Value[][] withFraction(Literal p, Value... xs) {
		Value[][] rows = new Value[xs.length][];
		for (int i = 0; i < xs.length; i++) {
			rows[i] = pair(xs[i], p);
		}
		return rows;
	}

	private static Value emptyGroupValue(Object factory) {
		if (factory instanceof CountIfAggregateFactory || factory instanceof ApproxCountDistinctAggregateFactory) {
			return integer(0);
		}
		if (factory instanceof HistogramAggregateFactory || factory instanceof ArrayAggAggregateFactory) {
			return EMPTY_JSON_ARRAY;
		}
		return null;
	}

	// ------------------------------------------------------------------ family-wide

	@Test
	void emptyGroupIsUnboundExceptCountsAndArrays() {
		for (AbstractUnaryAggregateFactory factory : UNARY) {
			assertThat(unary(factory, false)).as(factory.getIri()).isEqualTo(emptyGroupValue(factory));
		}
		for (AbstractNAryAggregateFactory factory : NARY) {
			assertThat(nary(factory, false)).as(factory.getIri()).isNull();
		}
	}

	@Test
	void groupWithOnlyUnboundValuesBehavesLikeEmptyGroup() {
		// pins current behaviour: unbound values are skipped, so an all-unbound group is an empty group (no error)
		for (AbstractUnaryAggregateFactory factory : UNARY) {
			assertThat(unary(factory, false, null, null, null)).as(factory.getIri())
					.isEqualTo(emptyGroupValue(factory));
		}
		for (AbstractNAryAggregateFactory factory : NARY) {
			assertThat(nary(factory, false, pair(null, integer(1)), pair(integer(1), null), pair(null, null)))
					.as(factory.getIri())
					.isNull();
		}
	}

	@Test
	void singleErroringValuePoisonsTypedAggregates() {
		// one non-numeric value among valid ones: the whole aggregate is an error (unbound in SPARQL)
		assertThatThrownBy(() -> unary(new MedianAggregateFactory(), false, integer(1), str("two"), integer(3)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> unary(new MedianAggregateFactory(), false, integer(1), VF.createIRI("urn:x")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> unary(new MedianAggregateFactory(), false, integer(1),
				VF.createLiteral("abc", XSD.INTEGER))).isInstanceOf(ValueExprEvaluationException.class);
		for (AbstractNAryAggregateFactory factory : List.of(new PercentileContAggregateFactory(),
				new PercentileDiscAggregateFactory(), new ApproxQuantileAggregateFactory())) {
			assertThatThrownBy(() -> nary(factory, false, pair(integer(1), decimal("0.5")),
					pair(str("two"), decimal("0.5")), pair(integer(3), decimal("0.5")))).as(factory.getIri())
							.isInstanceOf(ValueExprEvaluationException.class);
		}
		for (AbstractNAryAggregateFactory factory : List.of(new CorrAggregateFactory(),
				new CovarPopAggregateFactory(), new CovarSampAggregateFactory())) {
			assertThatThrownBy(() -> nary(factory, false, pair(integer(1), integer(1)),
					pair(integer(2), VF.createLiteral(true)), pair(integer(3), integer(3)))).as(factory.getIri())
							.isInstanceOf(ValueExprEvaluationException.class);
		}
		assertThatThrownBy(() -> unary(new BoolAndAggregateFactory(), false, VF.createLiteral(true),
				VF.createIRI("urn:x"), VF.createLiteral(true))).isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> unary(new BoolOrAggregateFactory(), false, VF.createLiteral(false),
				VF.createBNode(), VF.createLiteral(false))).isInstanceOf(ValueExprEvaluationException.class);
		// the error is sticky: valid values processed after it do not resurrect the aggregate
		ExtensionCollector collector = new MedianAggregateFactory().getCollector();
		AggregateFunction<ExtensionCollector, Value> function = new MedianAggregateFactory()
				.buildFunction(bs -> bs.getValue("x"));
		function.processAggregate(row(str("x")), v -> true, collector);
		assertThat(collector.hasError()).isTrue();
		function.processAggregate(row(integer(1)), v -> true, collector);
		assertThatThrownBy(collector::getFinalValue).isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void erroringExpressionRowIsSkippedNotPoisoning() {
		// pins current behaviour: an evaluation error of the argument *expression* (as opposed to an unsuitable
		// value) is treated like an unbound value, in the same way COUNT skips rows whose expression errors
		Function<BindingSet, Value> step = bs -> {
			Value v = bs.getValue("x");
			if (v instanceof Literal literal && literal.getLabel().equals("boom")) {
				throw new ValueExprEvaluationException("boom");
			}
			return v;
		};
		assertThat(unaryWith(new MedianAggregateFactory(), false, step, integer(1), str("boom"), integer(3)))
				.isEqualTo(decimal("2"));
		assertThat(unaryWith(new CountIfAggregateFactory(), false, step, VF.createLiteral(true), str("boom")))
				.isEqualTo(integer(1));
		assertThat(unaryWith(new FirstAggregateFactory(), false, step, str("boom"), integer(7))).isEqualTo(integer(7));
	}

	@Test
	void mixedNumericDatatypesPromoteAndMixedStringNumberErrors() {
		// integer + decimal stay exact (decimal result); any float/double makes the result a double
		assertThat(unary(new MedianAggregateFactory(), false, integer(1), decimal("2.5"))).isEqualTo(decimal("1.75"));
		Literal promoted = (Literal) unary(new MedianAggregateFactory(), false, integer(1), decimal("2.5"), dbl(4.0));
		assertThat(promoted.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DOUBLE);
		assertThat(promoted.doubleValue()).isEqualTo(2.5);
		Literal viaFloat = (Literal) unary(new MedianAggregateFactory(), false, integer(1), VF.createLiteral(3.0f));
		assertThat(viaFloat.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DOUBLE);
		assertThat(viaFloat.doubleValue()).isEqualTo(2.0);
		Literal derived = (Literal) unary(new MedianAggregateFactory(), false, VF.createLiteral("1", XSD.BYTE),
				VF.createLiteral("3", XSD.UNSIGNED_LONG), VF.createLiteral("5", XSD.POSITIVE_INTEGER));
		assertThat(derived).isEqualTo(decimal("3"));
		// percentiles and co-moments promote the same way
		Literal middle = (Literal) nary(new PercentileContAggregateFactory(), false,
				withFraction(decimal("0.5"), integer(1), decimal("2.0"), integer(3)));
		assertThat(middle.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DECIMAL);
		assertThat(middle.decimalValue()).isEqualByComparingTo("2");
		Literal corr = (Literal) nary(new CorrAggregateFactory(), false, pair(integer(1), dbl(1.0)),
				pair(decimal("2.0"), VF.createLiteral(2.0f)), pair(integer(3), integer(3)));
		assertThat(corr.doubleValue()).isCloseTo(1.0, within(1e-12));
		// a string among numbers is an error for every numeric aggregate
		assertThatThrownBy(() -> unary(new MedianAggregateFactory(), false, integer(1), str("2")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> nary(new CovarPopAggregateFactory(), false, pair(integer(1), str("2"))))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> nary(new ApproxQuantileAggregateFactory(), false, pair(str("1"), decimal("0.5"))))
				.isInstanceOf(ValueExprEvaluationException.class);
		// a language-tagged "number" is a string, not a number
		assertThatThrownBy(() -> unary(new MedianAggregateFactory(), false, VF.createLiteral("1", "en")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void largeGroupsCompleteInReasonableTime() {
		int n = 100_000;
		List<Value> values = new ArrayList<>(n);
		for (int i = 1; i <= n; i++) {
			values.add(integer(i));
		}
		Collections.shuffle(values, new Random(42));
		Value[] array = values.toArray(new Value[0]);
		long start = System.nanoTime();
		assertThat(unary(new MedianAggregateFactory(), false, array)).isEqualTo(decimal("50000.5"));
		assertThat(nary(new PercentileDiscAggregateFactory(), false, withFraction(decimal("0.9"), array)))
				.isEqualTo(integer(90_000));
		assertThat(unary(new ModeAggregateFactory(), false, array)).isEqualTo(array[0]);
		Literal arrayAgg = (Literal) unary(new ArrayAggAggregateFactory(), false, array);
		assertThat(arrayAgg.getLabel()).startsWith("[").endsWith("]").hasSizeGreaterThan(n * 2);
		Literal histogram = (Literal) unary(new HistogramAggregateFactory(), false, array);
		assertThat(histogram.getLabel()).startsWith("[{\"value\":1,\"count\":1},{\"value\":2,\"count\":1}");
		Literal approx = (Literal) nary(new ApproxQuantileAggregateFactory(), false,
				withFraction(decimal("0.5"), array));
		assertThat(approx.doubleValue()).isBetween(47_000.0, 53_000.0);
		Literal distinct = (Literal) unary(new ApproxCountDistinctAggregateFactory(), false, array);
		assertThat(distinct.longValue()).isBetween(98_000L, 102_000L);
		Value[][] pairs = new Value[n][];
		for (int i = 0; i < n; i++) {
			pairs[i] = pair(array[i], integer(2L * ((Literal) array[i]).longValue() + 1));
		}
		assertThat(((Literal) nary(new CorrAggregateFactory(), false, pairs)).doubleValue())
				.isCloseTo(1.0, within(1e-9));
		assertThat(nary(new ArgMaxAggregateFactory(), false, pairs)).isEqualTo(integer(n));
		long elapsedMillis = (System.nanoTime() - start) / 1_000_000;
		assertThat(elapsedMillis).as("all aggregates over %d values took %d ms", n, elapsedMillis)
				.isLessThan(30_000);
	}

	@Test
	void sketchAggregatesUseBoundedMemoryStructures() {
		// the sketch collectors must not retain the input: their only state is the datasketches sketch (plus
		// primitives); no collection, map or array of values may be declared
		assertSketchOnly(new ApproxCountDistinctAggregateFactory().getCollector(), HllSketch.class);
		assertSketchOnly(new ApproxQuantileAggregateFactory().getCollector(), KllDoublesSketch.class);
	}

	private static void assertSketchOnly(ExtensionCollector collector, Class<?> sketchType) {
		boolean sketchSeen = false;
		for (Field field : collector.getClass().getDeclaredFields()) {
			if (Modifier.isStatic(field.getModifiers()) || field.isSynthetic()) {
				continue;
			}
			Class<?> type = field.getType();
			assertThat(Collection.class.isAssignableFrom(type) || Map.class.isAssignableFrom(type) || type.isArray())
					.as("field %s of %s retains values", field.getName(), collector.getClass())
					.isFalse();
			sketchSeen |= sketchType.isAssignableFrom(type);
		}
		assertThat(sketchSeen).as("%s uses a %s", collector.getClass(), sketchType).isTrue();
	}

	@Test
	void eachCollectorIsIndependentAndRepeatable() {
		// same inputs evaluated twice give identical results: getCollector() hands out fresh state every time
		for (AbstractUnaryAggregateFactory factory : UNARY) {
			assertThat(factory.getCollector()).isNotSameAs(factory.getCollector());
			Value first = unary(factory, false, integer(1), integer(2), integer(2));
			Value second = unary(factory, false, integer(1), integer(2), integer(2));
			assertThat(second).as(factory.getIri()).isEqualTo(first);
		}
		for (AbstractNAryAggregateFactory factory : NARY) {
			assertThat(factory.getCollector()).isNotSameAs(factory.getCollector());
			Value[][] rows = { pair(integer(1), decimal("0.5")), pair(integer(2), decimal("0.5")) };
			assertThat(nary(factory, false, rows)).as(factory.getIri()).isEqualTo(nary(factory, false, rows));
		}
	}

	// ------------------------------------------------------------------ median

	@Test
	void medianOddEvenAndSingleCounts() {
		assertThat(unary(new MedianAggregateFactory(), false, integer(5), integer(1), integer(9), integer(3),
				integer(7))).isEqualTo(decimal("5"));
		assertThat(unary(new MedianAggregateFactory(), false, integer(9), integer(1), integer(3), integer(7)))
				.isEqualTo(decimal("5"));
		assertThat(unary(new MedianAggregateFactory(), false, integer(10), integer(1))).isEqualTo(decimal("5.5"));
		assertThat(unary(new MedianAggregateFactory(), false, integer(42))).isEqualTo(decimal("42"));
		assertThat(unary(new MedianAggregateFactory(), false, dbl(42.0))).isEqualTo(dbl(42.0));
	}

	@Test
	void medianResultDatatypeFollowsInput() {
		// pins current behaviour (doc: "exact for integer and decimal input" as xsd:decimal): an integer-only group
		// yields an xsd:decimal even when the median is a whole number, never an xsd:integer
		Literal whole = (Literal) unary(new MedianAggregateFactory(), false, integer(1), integer(2), integer(3));
		assertThat(whole.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DECIMAL);
		assertThat(whole.getLabel()).isEqualTo("2");
		Literal half = (Literal) unary(new MedianAggregateFactory(), false, integer(1), integer(2));
		assertThat(half.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DECIMAL);
		assertThat(half.getLabel()).isEqualTo("1.5");
		Literal decimals = (Literal) unary(new MedianAggregateFactory(), false, decimal("1.10"), decimal("1.30"));
		assertThat(decimals.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DECIMAL);
		assertThat(decimals.decimalValue()).isEqualByComparingTo("1.2");
		Literal doubles = (Literal) unary(new MedianAggregateFactory(), false, dbl(1.0), dbl(2.0));
		assertThat(doubles.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DOUBLE);
		assertThat(doubles.doubleValue()).isEqualTo(1.5);
	}

	@Test
	void medianOfTwoIsExactlyOnePointFive() {
		Literal median = (Literal) unary(new MedianAggregateFactory(), false, integer(1), integer(2));
		assertThat(median.getLabel()).isEqualTo("1.5");
		assertThat(median.decimalValue()).isEqualByComparingTo(new BigDecimal("1.5"));
		// decimals that are not exactly representable as doubles stay exact
		Literal tenths = (Literal) unary(new MedianAggregateFactory(), false, decimal("0.1"), decimal("0.2"));
		assertThat(tenths.getLabel()).isEqualTo("0.15");
	}

	@Test
	void medianDistinctAveragesTheDistinctMiddles() {
		assertThat(unary(new MedianAggregateFactory(), true, integer(1), integer(1), integer(2)))
				.isEqualTo(decimal("1.5"));
		assertThat(unary(new MedianAggregateFactory(), false, integer(1), integer(1), integer(2)))
				.isEqualTo(decimal("1"));
	}

	// ------------------------------------------------------------------ mode

	@Test
	void modeTieKeepsFirstSeen() {
		// pins current behaviour: ties between the most frequent terms resolve to the term seen first
		assertThat(unary(new ModeAggregateFactory(), false, integer(2), integer(1), integer(1), integer(2)))
				.isEqualTo(integer(2));
		assertThat(unary(new ModeAggregateFactory(), false, integer(1), integer(2), integer(2), integer(1)))
				.isEqualTo(integer(1));
		assertThat(unary(new ModeAggregateFactory(), false, integer(3), integer(1), integer(3), integer(1)))
				.isEqualTo(integer(3));
	}

	@Test
	void modeOfAllDistinctValuesIsFirstSeen() {
		// pins current behaviour: every term appears once, so the first one wins (no error)
		assertThat(unary(new ModeAggregateFactory(), false, integer(9), integer(1), integer(5))).isEqualTo(integer(9));
		assertThat(unary(new ModeAggregateFactory(), false, str("z"), str("a"))).isEqualTo(str("z"));
	}

	@Test
	void modeSupportsNonNumericTerms() {
		IRI iri = VF.createIRI("urn:a");
		BNode bnode = VF.createBNode("b1");
		assertThat(unary(new ModeAggregateFactory(), false, str("a"), iri, iri, str("a"), iri)).isEqualTo(iri);
		assertThat(unary(new ModeAggregateFactory(), false, str("a"), bnode, bnode)).isEqualTo(bnode);
		assertThat(unary(new ModeAggregateFactory(), false, VF.createLiteral("s", "en"), VF.createLiteral("s", "de"),
				VF.createLiteral("s", "en"))).isEqualTo(VF.createLiteral("s", "en"));
		// mode compares RDF terms, so 1 and 1.0 are different candidates
		assertThat(unary(new ModeAggregateFactory(), false, decimal("1.0"), integer(1), decimal("1.0")))
				.isEqualTo(decimal("1.0"));
	}

	// ------------------------------------------------------------------ countIf

	@Test
	void countIfTreatsUnboundAndErroringConditionsAsFalse() {
		assertThat(unary(new CountIfAggregateFactory(), false, VF.createLiteral(true), null, VF.createLiteral(true),
				null)).isEqualTo(integer(2));
		Function<BindingSet, Value> step = bs -> {
			Value v = bs.getValue("x");
			if (v == null) {
				throw new ValueExprEvaluationException("unbound");
			}
			return v;
		};
		assertThat(unaryWith(new CountIfAggregateFactory(), false, step, VF.createLiteral(true), null,
				VF.createLiteral(false))).isEqualTo(integer(1));
		// a value without an effective boolean value is not counted and does not poison the aggregate
		assertThat(unary(new CountIfAggregateFactory(), false, VF.createLiteral(true), VF.createIRI("urn:x"),
				VF.createBNode(), VF.createLiteral("1", XSD.DATE))).isEqualTo(integer(1));
	}

	@Test
	void countIfCoercesNonBooleanConditionsThroughEbv() {
		// pins current behaviour: the condition is coerced with the SPARQL effective boolean value, so "yes"
		// (non-empty string) counts, "" and 0 and NaN do not; a language-tagged literal has no EBV in RDF4J
		// (QueryEvaluationUtil) and is therefore not counted either
		assertThat(unary(new CountIfAggregateFactory(), false, str("yes"), str(""), integer(0), integer(7),
				dbl(Double.NaN), decimal("0.0"), VF.createLiteral("false", XSD.BOOLEAN), VF.createLiteral("1", "en")))
						.isEqualTo(integer(2));
	}

	@Test
	void countIfDistinctCountsDistinctConditionValues() {
		// pins current behaviour: DISTINCT applies to the condition's value, so a group with many true rows yields 1
		assertThat(unary(new CountIfAggregateFactory(), true, VF.createLiteral(true), VF.createLiteral(true),
				VF.createLiteral(false), VF.createLiteral(true))).isEqualTo(integer(1));
		// distinct non-boolean truthy terms each count once
		assertThat(unary(new CountIfAggregateFactory(), true, str("a"), str("a"), str("b"), integer(1)))
				.isEqualTo(integer(3));
	}

	// ------------------------------------------------------------------ boolAnd / boolOr

	@Test
	void boolAndBoolOrOnBooleanGroups() {
		assertThat(unary(new BoolAndAggregateFactory(), false)).isNull();
		assertThat(unary(new BoolOrAggregateFactory(), false)).isNull();
		assertThat(unary(new BoolAndAggregateFactory(), false, VF.createLiteral(true), VF.createLiteral(true),
				VF.createLiteral(true))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(unary(new BoolOrAggregateFactory(), false, VF.createLiteral(false), VF.createLiteral(false),
				VF.createLiteral(true), VF.createLiteral(false))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(unary(new BoolAndAggregateFactory(), false, VF.createLiteral(true), VF.createLiteral(false),
				VF.createLiteral(true))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(unary(new BoolOrAggregateFactory(), false, VF.createLiteral(false))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(unary(new BoolAndAggregateFactory(), false, VF.createLiteral(false)))
				.isEqualTo(BooleanLiteral.FALSE);
	}

	@Test
	void boolAndBoolOrCoerceLiteralsAndIgnoreUnbound() {
		// pins current behaviour: non-boolean literals are coerced through the effective boolean value, unbound rows
		// are ignored, and a term without an EBV (IRI, bnode, date) poisons the aggregate
		assertThat(unary(new BoolAndAggregateFactory(), false, str("yes"), integer(2), dbl(0.5)))
				.isEqualTo(BooleanLiteral.TRUE);
		assertThat(unary(new BoolAndAggregateFactory(), false, str("yes"), str(""))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(unary(new BoolOrAggregateFactory(), false, str(""), integer(0), decimal("0.0")))
				.isEqualTo(BooleanLiteral.FALSE);
		assertThat(unary(new BoolOrAggregateFactory(), false, str(""), str("x"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(unary(new BoolAndAggregateFactory(), false, null, VF.createLiteral(true), null))
				.isEqualTo(BooleanLiteral.TRUE);
		assertThat(unary(new BoolOrAggregateFactory(), false, null, VF.createLiteral(false), null))
				.isEqualTo(BooleanLiteral.FALSE);
		assertThatThrownBy(() -> unary(new BoolOrAggregateFactory(), false, VF.createLiteral(true),
				VF.createLiteral("2020-01-01", XSD.DATE))).isInstanceOf(ValueExprEvaluationException.class);
	}

	// ------------------------------------------------------------------ first / last

	@Test
	void firstAndLastFollowEvaluationOrder() {
		assertThat(unary(new FirstAggregateFactory(), false, integer(3), integer(1), integer(2))).isEqualTo(integer(3));
		assertThat(unary(new LastAggregateFactory(), false, integer(3), integer(1), integer(2))).isEqualTo(integer(2));
		// reversing the input reverses the answers: no sorting is involved
		assertThat(unary(new FirstAggregateFactory(), false, integer(2), integer(1), integer(3))).isEqualTo(integer(2));
		assertThat(unary(new LastAggregateFactory(), false, integer(2), integer(1), integer(3))).isEqualTo(integer(3));
	}

	@Test
	void firstAndLastWithValuesOfDifferentTypes() {
		IRI iri = VF.createIRI("urn:first");
		BNode bnode = VF.createBNode("last");
		assertThat(unary(new FirstAggregateFactory(), false, iri, integer(1), str("s"), bnode)).isEqualTo(iri);
		assertThat(unary(new LastAggregateFactory(), false, iri, integer(1), str("s"), bnode)).isEqualTo(bnode);
		assertThat(unary(new FirstAggregateFactory(), false, VF.createLiteral("abc", XSD.INTEGER), integer(1)))
				.isEqualTo(VF.createLiteral("abc", XSD.INTEGER));
	}

	@Test
	void firstAndLastWithDistinctStillFollowOrder() {
		assertThat(unary(new FirstAggregateFactory(), true, integer(2), integer(2), integer(1))).isEqualTo(integer(2));
		assertThat(unary(new LastAggregateFactory(), true, integer(1), integer(2), integer(1))).isEqualTo(integer(2));
	}

	// ------------------------------------------------------------------ approxCountDistinct

	@Test
	void approxCountDistinctIsExactForSmallSets() {
		for (int distinct : new int[] { 1, 7, 50, 100 }) {
			List<Value> values = new ArrayList<>();
			for (int repeat = 0; repeat < 3; repeat++) {
				for (int i = 0; i < distinct; i++) {
					values.add(VF.createIRI("urn:item:" + i));
				}
			}
			Literal estimate = (Literal) unary(new ApproxCountDistinctAggregateFactory(), false,
					values.toArray(new Value[0]));
			assertThat(estimate.longValue()).as("%d distinct", distinct).isEqualTo(distinct);
		}
	}

	@Test
	void approxCountDistinctIsWithinTwoPercentForLargeSets() {
		int distinct = 100_000;
		Value[] values = new Value[distinct * 2];
		for (int i = 0; i < distinct; i++) {
			values[i] = integer(i);
			values[distinct + i] = integer(i); // duplicates must not inflate the estimate
		}
		Literal estimate = (Literal) unary(new ApproxCountDistinctAggregateFactory(), false, values);
		assertThat(estimate.longValue()).isBetween(98_000L, 102_000L);
	}

	@Test
	void approxCountDistinctDistinguishesTermsLikeDistinct() {
		// pins current behaviour: terms are compared as RDF terms (consistent with DISTINCT), so 1 and 1.0 are two
		// values while 1 and "1"^^xsd:integer are the same term
		assertThat(unary(new ApproxCountDistinctAggregateFactory(), false, integer(1), decimal("1.0"),
				VF.createLiteral("1", XSD.INTEGER))).isEqualTo(integer(2));
		assertThat(unary(new ApproxCountDistinctAggregateFactory(), false, str("a"), VF.createLiteral("a", "en"),
				VF.createIRI("urn:a"))).isEqualTo(integer(3));
	}

	@Test
	void approxCountDistinctEmptyGroupIsIntegerZero() {
		Literal zero = (Literal) unary(new ApproxCountDistinctAggregateFactory(), false);
		assertThat(zero.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.INTEGER);
		assertThat(zero.getLabel()).isEqualTo("0");
		Literal one = (Literal) unary(new ApproxCountDistinctAggregateFactory(), false, integer(5));
		assertThat(one.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.INTEGER);
		assertThat(one.getLabel()).isEqualTo("1");
	}

	// ------------------------------------------------------------------ histogram

	@Test
	void histogramBucketsAreOrderedByValueRegardlessOfInputOrder() {
		Literal ascending = (Literal) unary(new HistogramAggregateFactory(), false, integer(1), integer(2),
				integer(2), integer(3), integer(3), integer(3));
		Literal shuffled = (Literal) unary(new HistogramAggregateFactory(), false, integer(3), integer(2),
				integer(3), integer(1), integer(3), integer(2));
		assertThat(ascending.getCoreDatatype()).isEqualTo(CoreDatatype.RDF.JSON);
		assertThat(ascending.getLabel())
				.isEqualTo("[{\"value\":1,\"count\":1},{\"value\":2,\"count\":2},{\"value\":3,\"count\":3}]");
		assertThat(shuffled).isEqualTo(ascending);
		// numeric buckets follow numeric order, not lexical order
		assertThat(((Literal) unary(new HistogramAggregateFactory(), false, integer(10), integer(9))).getLabel())
				.isEqualTo("[{\"value\":9,\"count\":1},{\"value\":10,\"count\":1}]");
	}

	@Test
	void histogramEncodesTermsLosslessly() {
		Literal histogram = (Literal) unary(new HistogramAggregateFactory(), false, VF.createLiteral("s", "en"),
				VF.createIRI("urn:x"), VF.createLiteral("1", XSD.BYTE), VF.createLiteral("s", "en"), decimal("1.0"),
				dbl(Double.NaN));
		String label = histogram.getLabel();
		assertThat(label).contains("{\"value\":{\"@value\":\"s\",\"@language\":\"en\"},\"count\":2}");
		assertThat(label).contains("{\"value\":{\"@id\":\"urn:x\"},\"count\":1}");
		assertThat(label).contains(
				"{\"value\":{\"@value\":\"1\",\"@type\":\"http://www.w3.org/2001/XMLSchema#byte\"},\"count\":1}");
		assertThat(label).contains("{\"value\":1.0,\"count\":1}");
		assertThat(label).contains(
				"{\"value\":{\"@value\":\"NaN\",\"@type\":\"http://www.w3.org/2001/XMLSchema#double\"},\"count\":1}");
		// IRIs sort before literals under SPARQL ordering
		assertThat(label).startsWith("[{\"value\":{\"@id\":\"urn:x\"}");
	}

	@Test
	void histogramEmptyGroupIsEmptyArray() {
		assertThat(unary(new HistogramAggregateFactory(), false)).isEqualTo(EMPTY_JSON_ARRAY);
		assertThat(unary(new HistogramAggregateFactory(), false, null, null)).isEqualTo(EMPTY_JSON_ARRAY);
	}

	// ------------------------------------------------------------------ arrayAgg

	@Test
	void arrayAggPreservesOrderAndDuplicatesAndDistinctKeepsFirstSeenOrder() {
		assertThat(((Literal) unary(new ArrayAggAggregateFactory(), false, integer(3), integer(1), integer(3),
				integer(2))).getLabel()).isEqualTo("[3,1,3,2]");
		assertThat(((Literal) unary(new ArrayAggAggregateFactory(), true, integer(3), integer(1), integer(3),
				integer(2), integer(1))).getLabel()).isEqualTo("[3,1,2]");
	}

	@Test
	void arrayAggSkipsUnboundValues() {
		// pins current behaviour: unbound values are skipped, not encoded as JSON null
		assertThat(((Literal) unary(new ArrayAggAggregateFactory(), false, null, integer(1), null, integer(2), null))
				.getLabel()).isEqualTo("[1,2]");
		assertThat(unary(new ArrayAggAggregateFactory(), false, (Value) null)).isEqualTo(EMPTY_JSON_ARRAY);
	}

	@Test
	void arrayAggEncodesSpecialTermsLosslessly() {
		Literal array = (Literal) unary(new ArrayAggAggregateFactory(), false, dbl(Double.NaN),
				dbl(Double.POSITIVE_INFINITY), VF.createLiteral("1", XSD.BYTE), VF.createLiteral("1", XSD.INTEGER),
				VF.createLiteral("01", XSD.INTEGER), VF.createIRI("urn:x"), VF.createBNode("node1"), dbl(1.5));
		assertThat(array.getLabel()).isEqualTo("["
				+ "{\"@value\":\"NaN\",\"@type\":\"http://www.w3.org/2001/XMLSchema#double\"},"
				+ "{\"@value\":\"INF\",\"@type\":\"http://www.w3.org/2001/XMLSchema#double\"},"
				+ "{\"@value\":\"1\",\"@type\":\"http://www.w3.org/2001/XMLSchema#byte\"},"
				+ "1,"
				+ "{\"@value\":\"01\",\"@type\":\"http://www.w3.org/2001/XMLSchema#integer\"},"
				+ "{\"@id\":\"urn:x\"},"
				+ "{\"@id\":\"_:node1\"},"
				+ "{\"@value\":\"1.5\",\"@type\":\"http://www.w3.org/2001/XMLSchema#double\"}]");
		// pins current behaviour: a double becomes a JSON number only when its lexical form equals Java's
		// Double.toString (which carries an exponent only for magnitudes >= 1e7 or < 1e-3); "1.5" and "1.5E0" keep
		// the typed encoding so they decode back to the same lexical form
		assertThat(((Literal) unary(new ArrayAggAggregateFactory(), false, VF.createLiteral("1.0E10", XSD.DOUBLE)))
				.getLabel()).isEqualTo("[1.0E10]");
		assertThat(((Literal) unary(new ArrayAggAggregateFactory(), false, VF.createLiteral("1.5E0", XSD.DOUBLE)))
				.getLabel())
						.isEqualTo("[{\"@value\":\"1.5E0\",\"@type\":\"http://www.w3.org/2001/XMLSchema#double\"}]");
	}

	// ------------------------------------------------------------------ percentiles

	@Test
	void percentileFractionBoundsAndUnboundFraction() {
		Value[] xs = { integer(1), integer(2), integer(3), integer(4) };
		for (AbstractNAryAggregateFactory factory : List.of(new PercentileContAggregateFactory(),
				new PercentileDiscAggregateFactory(), new ApproxQuantileAggregateFactory())) {
			assertThat(((Literal) nary(factory, false, withFraction(integer(0), xs))).doubleValue())
					.as(factory.getIri() + " p=0")
					.isEqualTo(1.0);
			assertThat(((Literal) nary(factory, false, withFraction(integer(1), xs))).doubleValue())
					.as(factory.getIri() + " p=1")
					.isEqualTo(4.0);
			assertThatThrownBy(() -> nary(factory, false, withFraction(decimal("-0.01"), xs)))
					.as(factory.getIri() + " p<0")
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> nary(factory, false, withFraction(decimal("1.01"), xs)))
					.as(factory.getIri() + " p>1")
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> nary(factory, false, withFraction(integer(2), xs)))
					.as(factory.getIri() + " p=2")
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> nary(factory, false, withFraction(str("0.5"), xs)))
					.as(factory.getIri() + " p string")
					.isInstanceOf(ValueExprEvaluationException.class);
			// pins current behaviour: a row with an unbound fraction is skipped like any row with an unbound argument,
			// so an all-unbound fraction leaves the aggregate unbound (an error in SPARQL terms) rather than throwing
			assertThat(nary(factory, false, withFraction(null, xs))).as(factory.getIri() + " p unbound").isNull();
		}
	}

	@Test
	void percentileContInterpolatesExactlyForDecimals() {
		Literal p50 = (Literal) nary(new PercentileContAggregateFactory(), false,
				withFraction(decimal("0.5"), integer(1), integer(2), integer(3), integer(4)));
		assertThat(p50.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DECIMAL);
		assertThat(p50.getLabel()).isEqualTo("2.5");
		Literal p33 = (Literal) nary(new PercentileContAggregateFactory(), false,
				withFraction(decimal("0.1"), decimal("0.1"), decimal("0.2"), decimal("0.3"), decimal("0.4")));
		assertThat(p33.getLabel()).isEqualTo("0.13");
		Literal doubles = (Literal) nary(new PercentileContAggregateFactory(), false,
				withFraction(decimal("0.5"), dbl(1.0), dbl(2.0), dbl(3.0), dbl(4.0)));
		assertThat(doubles.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DOUBLE);
		assertThat(doubles.doubleValue()).isEqualTo(2.5);
	}

	@Test
	void percentileDiscPicksAnActualValueAndHandlesTies() {
		Literal p50 = (Literal) nary(new PercentileDiscAggregateFactory(), false,
				withFraction(decimal("0.5"), integer(1), integer(2), integer(3), integer(4)));
		assertThat(p50).isEqualTo(integer(2));
		// ties: the value whose cumulative distribution first reaches p
		assertThat(nary(new PercentileDiscAggregateFactory(), false,
				withFraction(decimal("0.5"), integer(1), integer(1), integer(2), integer(2)))).isEqualTo(integer(1));
		assertThat(nary(new PercentileDiscAggregateFactory(), false,
				withFraction(decimal("0.75"), integer(1), integer(1), integer(2), integer(2)))).isEqualTo(integer(2));
		// the original literal (datatype and lexical form) is returned, not a canonicalised copy
		Literal original = (Literal) nary(new PercentileDiscAggregateFactory(), false,
				withFraction(decimal("0.5"), decimal("1.0"), integer(2), VF.createLiteral("3", XSD.BYTE)));
		assertThat(original).isEqualTo(integer(2));
		Literal low = (Literal) nary(new PercentileDiscAggregateFactory(), false,
				withFraction(decimal("0.1"), decimal("1.0"), integer(2), VF.createLiteral("3", XSD.BYTE)));
		assertThat(low).isEqualTo(decimal("1.0"));
		assertThat(low.getLabel()).isEqualTo("1.0");
	}

	@Test
	void singleValueGroupYieldsThatValueForAnyFraction() {
		for (Literal p : List.of(integer(0), decimal("0.3"), decimal("0.999"), integer(1))) {
			assertThat(nary(new PercentileContAggregateFactory(), false, withFraction(p, integer(7))))
					.as("cont p=" + p)
					.isEqualTo(decimal("7"));
			assertThat(nary(new PercentileDiscAggregateFactory(), false, withFraction(p, integer(7))))
					.as("disc p=" + p)
					.isEqualTo(integer(7));
			assertThat(((Literal) nary(new ApproxQuantileAggregateFactory(), false, withFraction(p, integer(7))))
					.doubleValue()).as("approx p=" + p).isEqualTo(7.0);
		}
	}

	@Test
	void approxQuantileIsExactForTinyInputAndWithinErrorBoundForLargeInput() {
		Literal tiny = (Literal) nary(new ApproxQuantileAggregateFactory(), false,
				withFraction(decimal("0.5"), integer(5), integer(1), integer(3), integer(2), integer(4)));
		assertThat(tiny.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DOUBLE);
		assertThat(tiny.doubleValue()).isEqualTo(3.0);
		assertThat(((Literal) nary(new ApproxQuantileAggregateFactory(), false,
				withFraction(decimal("0.25"), integer(10), integer(20), integer(30), integer(40)))).doubleValue())
						.isEqualTo(10.0);
		int n = 100_000;
		List<Value> values = new ArrayList<>(n);
		for (int i = 1; i <= n; i++) {
			values.add(integer(i));
		}
		Collections.shuffle(values, new Random(7));
		Literal p90 = (Literal) nary(new ApproxQuantileAggregateFactory(), false,
				withFraction(decimal("0.9"), values.toArray(new Value[0])));
		// KLL (k = 200) normalised rank error is about 1.3% at 99% confidence; allow 3% of the rank range
		assertThat(p90.doubleValue()).isBetween(87_000.0, 93_000.0);
	}

	// ------------------------------------------------------------------ corr / covar

	@Test
	void singleRowCovarianceAndCorrelation() {
		Value[] single = pair(integer(3), integer(5));
		assertThat(nary(new CovarSampAggregateFactory(), false, single)).isNull();
		assertThat(nary(new CorrAggregateFactory(), false, single)).isNull();
		Literal covarPop = (Literal) nary(new CovarPopAggregateFactory(), false, single);
		assertThat(covarPop.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DOUBLE);
		assertThat(covarPop.doubleValue()).isEqualTo(0.0);
	}

	@Test
	void constantSeriesLeavesCorrelationUnbound() {
		// pins current behaviour: zero variance in either series makes corr unbound (not NaN), covariances are 0
		Value[][] constantX = { pair(integer(4), integer(1)), pair(integer(4), integer(2)),
				pair(integer(4), integer(3)) };
		assertThat(nary(new CorrAggregateFactory(), false, constantX)).isNull();
		assertThat(((Literal) nary(new CovarPopAggregateFactory(), false, constantX)).doubleValue()).isEqualTo(0.0);
		assertThat(((Literal) nary(new CovarSampAggregateFactory(), false, constantX)).doubleValue()).isEqualTo(0.0);
		Value[][] constantBoth = { pair(integer(4), integer(4)), pair(integer(4), integer(4)) };
		assertThat(nary(new CorrAggregateFactory(), false, constantBoth)).isNull();
	}

	@Test
	void perfectCorrelationIsOneWithinTolerance() {
		Value[][] positive = new Value[50][];
		Value[][] negative = new Value[50][];
		for (int i = 0; i < 50; i++) {
			double x = 0.1 * i + 3.7;
			positive[i] = pair(dbl(x), dbl(2.5 * x - 11.25));
			negative[i] = pair(dbl(x), dbl(-3.0 * x + 7.0));
		}
		assertThat(((Literal) nary(new CorrAggregateFactory(), false, positive)).doubleValue()).isCloseTo(1.0,
				within(1e-12));
		assertThat(((Literal) nary(new CorrAggregateFactory(), false, negative)).doubleValue()).isCloseTo(-1.0,
				within(1e-12));
		// covariances for the known series y = 2x: covarPop = 2 * var_pop(x)
		Value[][] rows = { pair(integer(1), integer(2)), pair(integer(2), integer(4)), pair(integer(3), integer(6)),
				pair(integer(4), integer(8)) };
		assertThat(((Literal) nary(new CovarPopAggregateFactory(), false, rows)).doubleValue()).isCloseTo(2.5,
				within(1e-12));
		assertThat(((Literal) nary(new CovarSampAggregateFactory(), false, rows)).doubleValue())
				.isCloseTo(10.0 / 3.0, within(1e-12));
	}

	@Test
	void rowWithOneUnboundSeriesValueIsSkipped() {
		// pins current behaviour: a row where x or y is unbound is skipped, the remaining pairs are aggregated
		Value[][] rows = { pair(integer(1), integer(2)), pair(integer(2), null), pair(null, integer(100)),
				pair(integer(3), integer(6)) };
		assertThat(((Literal) nary(new CorrAggregateFactory(), false, rows)).doubleValue()).isCloseTo(1.0,
				within(1e-12));
		assertThat(((Literal) nary(new CovarPopAggregateFactory(), false, rows)).doubleValue()).isEqualTo(2.0);
		assertThat(((Literal) nary(new CovarSampAggregateFactory(), false, rows)).doubleValue()).isEqualTo(4.0);
	}

	// ------------------------------------------------------------------ argMin / argMax

	@Test
	void argMinArgMaxTiesKeepFirstValue() {
		// pins current behaviour: among equal keys the value seen first is kept
		Value[][] rows = { pair(str("first"), integer(1)), pair(str("second"), integer(1)),
				pair(str("third"), decimal("1.0")) };
		assertThat(nary(new ArgMinAggregateFactory(), false, rows)).isEqualTo(str("first"));
		assertThat(nary(new ArgMaxAggregateFactory(), false, rows)).isEqualTo(str("first"));
	}

	@Test
	void argMinArgMaxSkipRowsWithUnboundKeyOrValue() {
		// pins current behaviour: a row with an unbound key is skipped, and so is a row with an unbound value even
		// when its key would be the extremum
		Value[][] rows = { pair(str("a"), integer(5)), pair(str("noKey"), null), pair(null, integer(0)),
				pair(null, integer(100)), pair(str("b"), integer(7)) };
		assertThat(nary(new ArgMinAggregateFactory(), false, rows)).isEqualTo(str("a"));
		assertThat(nary(new ArgMaxAggregateFactory(), false, rows)).isEqualTo(str("b"));
		assertThat(nary(new ArgMinAggregateFactory(), false, pair(null, integer(1)), pair(str("x"), null))).isNull();
	}

	@Test
	void argMinArgMaxOrderKeysWithSparqlOrdering() {
		// string keys: codepoint order ("C" < "a" < "b")
		Value[][] strings = { pair(integer(1), str("b")), pair(integer(2), str("a")), pair(integer(3), str("C")) };
		assertThat(nary(new ArgMinAggregateFactory(), false, strings)).isEqualTo(integer(3));
		assertThat(nary(new ArgMaxAggregateFactory(), false, strings)).isEqualTo(integer(1));
		// numeric keys compare by value across datatypes
		Value[][] numbers = { pair(str("int"), integer(2)), pair(str("dec"), decimal("1.5")),
				pair(str("dbl"), dbl(2.5)) };
		assertThat(nary(new ArgMinAggregateFactory(), false, numbers)).isEqualTo(str("dec"));
		assertThat(nary(new ArgMaxAggregateFactory(), false, numbers)).isEqualTo(str("dbl"));
		// pins current behaviour: mixed term kinds follow SPARQL ORDER BY (blank nodes < IRIs < literals)
		Value[][] mixed = { pair(str("literal"), integer(0)), pair(str("iri"), VF.createIRI("urn:k")),
				pair(str("bnode"), VF.createBNode("k")) };
		assertThat(nary(new ArgMinAggregateFactory(), false, mixed)).isEqualTo(str("bnode"));
		assertThat(nary(new ArgMaxAggregateFactory(), false, mixed)).isEqualTo(str("literal"));
	}

	@Test
	void argMinArgMaxDistinctDoesNotChangeTheResult() {
		Value[][] rows = { pair(str("a"), integer(2)), pair(str("a"), integer(2)), pair(str("b"), integer(1)),
				pair(str("c"), integer(3)), pair(str("c"), integer(3)) };
		assertThat(nary(new ArgMinAggregateFactory(), true, rows)).isEqualTo(nary(new ArgMinAggregateFactory(),
				false, rows));
		assertThat(nary(new ArgMaxAggregateFactory(), true, rows)).isEqualTo(nary(new ArgMaxAggregateFactory(),
				false, rows));
		assertThat(nary(new ArgMinAggregateFactory(), true, rows)).isEqualTo(str("b"));
		assertThat(nary(new ArgMaxAggregateFactory(), true, rows)).isEqualTo(str("c"));
	}
}
